html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = (frappe.db.get_value("Company", company, "company_logo") if company else "") or "/files/AP_Logo.png" %}
{% set items = doc.checklist_items or [] %}
{% set done_count = items|selectattr("completed")|list|length %}

<style>
  @page { size: A4; margin: 8mm; }
  body { margin: 0; padding: 0; font-family: Arial, sans-serif; color: #000; }
  .sc-page { width: 100%; box-sizing: border-box; font-size: 12px; }

  .sc-head { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
  .sc-head td { vertical-align: middle; padding: 0; }
  .sc-logo { width: 140px; }
  .sc-logo img { width: 130px; height: 50px; display: block; }
  .sc-company { font-size: 15px; font-weight: 700; text-transform: uppercase; }
  .sc-company-sub { font-size: 11px; color: #333; }
  .sc-title { text-align: right; font-size: 20px; font-weight: 700; text-transform: uppercase; }

  .sc-rule { border-top: 2px solid #000; margin: 4px 0 8px 0; }

  .sc-info { width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: 10px; }
  .sc-info td { border: 1px solid #000; padding: 4px 6px; font-size: 11px; vertical-align: top; }
  .sc-info .lbl { width: 16%; background: #f0f0f0; font-weight: 700; }
  .sc-info .val { width: 34%; }

  .sc-list { width: 100%; border-collapse: collapse; table-layout: fixed; }
  .sc-list th, .sc-list td { border: 1px solid #000; padding: 4px 6px; font-size: 11px; line-height: 1.3; vertical-align: middle; }
  .sc-list th { background: #f0f0f0; font-weight: 700; text-align: center; }
  .sc-list tr { page-break-inside: avoid; }
  .sc-list td.c { text-align: center; }
  .sc-box { display: inline-block; width: 14px; height: 14px; border: 1px solid #000; line-height: 14px; text-align: center; font-weight: 700; font-size: 12px; }

  .sc-summary { margin-top: 6px; font-size: 11px; }

  .sc-sign { width: 100%; border-collapse: collapse; margin-top: 26px; }
  .sc-sign td { width: 33%; text-align: center; font-size: 11px; padding-top: 28px; }
  .sc-sign .line { border-top: 1px solid #000; margin: 0 14px; padding-top: 3px; }

  .sc-foot { margin-top: 10px; text-align: center; font-size: 10px; color: #555; }
</style>

<div class="sc-page">

  <table class="sc-head">
    <tr>
      <td class="sc-logo"><img src="{{ company_logo }}" alt="Company Logo" width="130" height="50"></td>
      <td>
        <div class="sc-company">Asia Petrochemicals LLC OPC</div>
        <div class="sc-company-sub">Plot # A 23 B, Al Jazeera Industrial Area, Ras Al-Khaimah</div>
      </td>
      <td class="sc-title">Security Checklist</td>
    </tr>
  </table>
  <div class="sc-rule"></div>

  <table class="sc-info">
    <tr>
      <td class="lbl">Inspection No.</td><td class="val">{{ doc.name }}</td>
      <td class="lbl">Date</td><td class="val">{{ frappe.utils.formatdate(doc.inspection_date) if doc.inspection_date else "-" }}</td>
    </tr>
    <tr>
      <td class="lbl">Job Order</td><td class="val">{{ doc.job_order or "-" }}</td>
      <td class="lbl">Customer</td><td class="val">{{ doc.customer_name or doc.customer or "-" }}</td>
    </tr>
    <tr>
      <td class="lbl">Vehicle No.</td><td class="val">{{ doc.vehicle_number or "-" }}</td>
      <td class="lbl">Trailer No.</td><td class="val">{{ doc.trailer_no or "-" }}</td>
    </tr>
    <tr>
      <td class="lbl">Driver</td><td class="val">{{ doc.driver_name or "-" }}</td>
      <td class="lbl">Driver Phone</td><td class="val">{{ doc.driver_phone or "-" }}</td>
    </tr>
    <tr>
      <td class="lbl">Container No.</td><td class="val">{{ doc.container_number or "-" }}</td>
      <td class="lbl">Seal No.</td><td class="val">{{ doc.seal_number or "-" }}</td>
    </tr>
    <tr>
      <td class="lbl">Material</td><td class="val">{{ doc.material_description or "-" }}</td>
      <td class="lbl">Quantity</td><td class="val">{{ doc.quantity or "-" }} {{ doc.uom or "" }}</td>
    </tr>
  </table>

  <table class="sc-list">
    <thead>
      <tr>
        <th style="width:6%;">S No.</th>
        <th style="width:52%;">Checklist Item</th>
        <th style="width:10%;">Required</th>
        <th style="width:8%;">Done</th>
        <th style="width:24%;">Remarks</th>
      </tr>
    </thead>
    <tbody>
      {% for row in items %}
      <tr>
        <td class="c">{{ loop.index }}</td>
        <td>{{ row.checklist_item }}</td>
        <td class="c">{{ "Yes" if row.required else "-" }}</td>
        <td class="c"><span class="sc-box">{% if row.completed %}&#10003;{% endif %}</span></td>
        <td>{{ row.remarks or "" }}</td>
      </tr>
      {% else %}
      <tr><td colspan="5" class="c">No checklist items on this inspection.</td></tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="sc-summary">Completed: <b>{{ done_count }}</b> of <b>{{ items|length }}</b> items{% if doc.security_remarks %} &nbsp;|&nbsp; Remarks: {{ doc.security_remarks }}{% endif %}</div>

  <table class="sc-sign">
    <tr>
      <td><div class="line">Security Officer</div></td>
      <td><div class="line">Driver</div></td>
      <td><div class="line">Supervisor</div></td>
    </tr>
  </table>

  <div class="sc-foot">Printed on {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm") }} &nbsp;|&nbsp; This is a Computer Generated Document</div>
</div>
